ALTER TABLE groups_competition ADD COLUMN group_code VARCHAR(20) NULL AFTER name, ADD COLUMN max_teams INT UNSIGNED NULL AFTER group_order, ADD COLUMN status VARCHAR(30) NOT NULL DEFAULT 'draft' AFTER max_teams;
CREATE TABLE IF NOT EXISTS group_team_assignments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,group_id BIGINT UNSIGNED NOT NULL,team_id BIGINT UNSIGNED NOT NULL,display_order INT NOT NULL DEFAULT 0,status VARCHAR(30) NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,UNIQUE KEY group_team(group_id,team_id),FOREIGN KEY(group_id) REFERENCES groups_competition(id),FOREIGN KEY(team_id) REFERENCES teams(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS match_decisions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,match_id BIGINT UNSIGNED NOT NULL,decision_type VARCHAR(50) NOT NULL,reason TEXT NOT NULL,before_json JSON NULL,after_json JSON NULL,created_by BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL,FOREIGN KEY(match_id) REFERENCES matches(id),FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS bracket_links (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tournament_id BIGINT UNSIGNED NOT NULL,source_match_id BIGINT UNSIGNED NOT NULL,target_match_id BIGINT UNSIGNED NOT NULL,slot VARCHAR(10) NOT NULL,created_at DATETIME NOT NULL,UNIQUE KEY source_target(source_match_id,target_match_id,slot),FOREIGN KEY(tournament_id) REFERENCES tournaments(id),FOREIGN KEY(source_match_id) REFERENCES matches(id),FOREIGN KEY(target_match_id) REFERENCES matches(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
